// Centralized Lesson Vocabulary Data Layer for WordPix
// Synchronized from Figma Design (Node 44:2 — The Bedroom)

export interface VocabularyItem {
  id: string;
  label: string;
  phonetic: string;
  cefr?: string;
  img: string;
  topic: string;
  /**
   * What the picture shows, described WITHOUT naming the word.
   *
   * This is what makes image-selection exercises answerable without sight. The
   * assessment alt text previously read "Picture option A", which stops the
   * answer leaking but leaves a screen reader user with nothing to reason
   * about — "which picture shows a lamp?" was unanswerable by design.
   *
   * Required, not optional: a missing description silently degrades an
   * exercise back to unanswerable, so the compiler should catch it.
   *
   * Rule enforced by lessons_content.test.ts: the description must never
   * contain its own label or a stem of it.
   */
  description: string;
  hasWoman?: boolean;
}

export interface TopicCategory {
  id: string;
  name: string;
  itemsCount: number;
  description?: string;
  icon?: string;
}

export interface Lesson {
  id: string;
  name: string;
  topicId: string;
  wordIds: string[];
  description: string;
  story?: string;
}

/**
 * A themed collection of groups sharing one vocabulary set — "The Bedroom"
 * today, with room for more (`ExploreWorlds` already mocks up locked
 * "Bathroom"/"Kitchen" previews; this is the data shape they'd need to become
 * real).
 */
export interface CourseUnit {
  id: string;
  isRevision?: boolean;
  revisionKind?: "checkpoint" | "milestone";
  name: string;
  description: string;
  /**
   * The unit's scene illustration, when the design file has one.
   *
   * Optional because seven units genuinely have no scene art in Figma — only
   * word cards. Typing it as required would have meant either dropping those
   * units or pointing them at a file that does not exist, and a broken image
   * on the Explore grid is worse than a designed absence.
   */
  heroImage?: string;
  topics: TopicCategory[];
  groups: Lesson[];
  /**
   * The unit's word ids, in curriculum order — not the words themselves.
   *
   * Ids are enough for the things the catalogue is asked at startup: how many
   * words a unit has, how many of them a learner has mastered, and whether a
   * search term matches one. The items behind them arrive per unit through
   * `data/vocabulary.ts`.
   */
  wordIds: string[];
}

const LOCAL_SCENE_IMAGES = "./scene-images";

